import{_ as c,C as d,o as a,c as h,a2 as i,b as n,w as t,a as r,E as s,a3 as l}from"./chunks/framework.RycU2wFZ.js";const A=JSON.parse('{"title":"AgentPay Configuration Publishing & Runtime Cache Specification (T1.4 Specification)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/config-publishing.md","filePath":"specs/config-publishing.md","lastUpdated":1792396280000}'),u={name:"specs/config-publishing.md"};function g(p,e,m,f,b,_){const o=d("Mermaid");return a(),h("div",null,[e[2]||(e[2]=i('<h1 id="agentpay-configuration-publishing-runtime-cache-specification-t1-4-specification" tabindex="-1">AgentPay Configuration Publishing &amp; Runtime Cache Specification (T1.4 Specification) <a class="header-anchor" href="#agentpay-configuration-publishing-runtime-cache-specification-t1-4-specification" aria-label="Permalink to &quot;AgentPay Configuration Publishing &amp; Runtime Cache Specification (T1.4 Specification)&quot;">​</a></h1><blockquote><p><strong>Version</strong>: v2.0.0 (T1.4 Unified Specification)<br><strong>Status</strong>: <strong>Approved Specification</strong><br><strong>Scope</strong>: Web Management Console (Control Plane), Go Gateway (Data Plane), PostgreSQL Configuration Persistence<br><strong>Machine-Readable Schemas</strong>:</p><ul><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/conformance/config-snapshot.schema.json" target="_blank" rel="noreferrer"><code>specs/conformance/config-snapshot.schema.json</code></a> (Immutable Snapshot JSON Schema)</li><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/test-vectors/config-publishing.json" target="_blank" rel="noreferrer"><code>specs/test-vectors/config-publishing.json</code></a> (Configuration Publishing &amp; Rollback Test Vectors)</li></ul></blockquote><hr><h2 id="_1-core-design-principles" tabindex="-1">1. Core Design Principles <a class="header-anchor" href="#_1-core-design-principles" aria-label="Permalink to &quot;1. Core Design Principles&quot;">​</a></h2><ol><li><strong>Strict Draft Isolation</strong>: <ul><li>Route or policy edits in <code>draft</code> state exist exclusively within the management console session or draft workspace and <strong>must never affect live Gateway traffic</strong>.</li></ul></li><li><strong>Immutable Snapshot &amp; Content Addressing</strong>: <ul><li>Upon publishing, the system immediately materializes a complete tenant configuration snapshot (containing all active Routes, Policies, and bindings for that tenant), assigns a monotonically increasing <code>version_number</code> and a deterministic SHA-256 content fingerprint (<code>snapshotHash</code>), and persists it in <code>ap_config_version</code>.</li><li>Published snapshots are <strong>strictly read-only and must never be updated or deleted</strong>.</li></ul></li><li><strong>Microsecond Atomic Hot-Swap on the Data Plane (Zero-Downtime RCU Swap)</strong>: <ul><li>The Go Gateway uses an in-memory Read-Copy-Update (RCU) atomic pointer swap. When a new version is activated, the Gateway atomically swaps its active configuration pointer to the new snapshot; in-flight requests continue referencing the previous snapshot until completion, while new requests immediately evaluate against the new rules with zero dropped connections or latency spikes.</li></ul></li><li><strong>Fail-Safe Degradation &amp; High Availability</strong>: <ul><li>If the control plane goes offline, the database experiences a transient outage, or a network partition occurs, the Gateway <strong>continues serving traffic without interruption</strong> using its in-memory snapshot and local disk cache.</li></ul></li></ol><hr><h2 id="_2-configuration-lifecycle-state-machine" tabindex="-1">2. Configuration Lifecycle State Machine <a class="header-anchor" href="#_2-configuration-lifecycle-state-machine" aria-label="Permalink to &quot;2. Configuration Lifecycle State Machine&quot;">​</a></h2>',7)),(a(),n(l,null,{default:t(()=>[s(o,{id:"mermaid-84",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20Draft%20%3A%20Created%20%2F%20edited%20by%20admin%0A%20%20%20%20Draft%20--%3E%20Validated%20%3A%20Static%20composite%20validation%20triggered%0A%20%20%20%20Draft%20--%3E%20Rejected%20%3A%20Format%20or%20logical%20conflict%20detected%0A%20%20%20%20Rejected%20--%3E%20Draft%20%3A%20Revised%20by%20admin%0A%20%20%20%20Validated%20--%3E%20Active%20%3A%20Published%20(generates%20immutable%20snapshot)%0A%20%20%20%20Active%20--%3E%20Superseded%20%3A%20Newer%20version%20published%20(auto-incremented)%0A%20%20%20%20Active%20--%3E%20RolledBack%20%3A%20One-click%20rollback%20executed%0A%20%20%20%20RolledBack%20--%3E%20Active%20%3A%20Rollback%20activates%20new%20snapshot%20version%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i('<table tabindex="0"><thead><tr><th>State</th><th>Scope</th><th>Visibility to Data Plane (Gateway)</th><th>Read/Write Permissions</th></tr></thead><tbody><tr><td><code>draft</code></td><td>Console draft workspace</td><td><strong>Invisible</strong> (never loaded)</td><td>Read/write editable</td></tr><tr><td><code>validated</code></td><td>Console validation staging</td><td><strong>Invisible</strong></td><td>Ready to publish</td></tr><tr><td><code>active</code></td><td>Production runtime</td><td><strong>Sole active version</strong></td><td>Read-only immutable</td></tr><tr><td><code>superseded</code></td><td>Historical archive</td><td>Referenced only for historical request tracing</td><td>Read-only immutable</td></tr><tr><td><code>rolled_back</code></td><td>Rollback archive</td><td>Retained for auditing and history</td><td>Read-only immutable</td></tr></tbody></table><hr><h2 id="_3-strict-static-validation-matrix" tabindex="-1">3. Strict Static Validation Matrix <a class="header-anchor" href="#_3-strict-static-validation-matrix" aria-label="Permalink to &quot;3. Strict Static Validation Matrix&quot;">​</a></h2><p>Before a configuration can be published, the control plane enforces the following <strong>static validation rules</strong>; any violation blocks publication:</p><h3 id="_3-1-route-validation-rules" tabindex="-1">3.1 Route Validation Rules <a class="header-anchor" href="#_3-1-route-validation-rules" aria-label="Permalink to &quot;3.1 Route Validation Rules&quot;">​</a></h3><ol><li><strong>URI Format Compliance</strong>: <code>upstream_url</code> must be a valid URI starting with <code>http://</code> or <code>https://</code>; private or malformed schemes are rejected.</li><li><strong>PathPattern Uniqueness</strong>: <code>path_pattern</code> must be strictly unique within the same tenant, preventing ambiguous overlapping route matches.</li><li><strong>Payee Address Validation</strong>: <code>payee_address</code> must be a valid Ethereum address matching <code>^0x[a-fA-F0-9]{40}$</code>.</li><li><strong>Non-Negative Pricing</strong>: <code>price_base_units &gt;= 0</code> (supports both free and paid routes).</li><li><strong>Payment Method Enum</strong>: <code>allowed_payment_methods</code> must be one of <code>wallet</code>, <code>onchain</code>, or <code>both</code>.</li></ol><h3 id="_3-2-policy-validation-rules" tabindex="-1">3.2 Policy Validation Rules <a class="header-anchor" href="#_3-2-policy-validation-rules" aria-label="Permalink to &quot;3.2 Policy Validation Rules&quot;">​</a></h3><ol><li><strong>Budget Hierarchy Check</strong>: The single-request cap must be less than or equal to the 24-hour rolling budget cap: $$\\text{max_amount_per_request} \\le \\text{rolling_24h_budget_cap}$$</li><li><strong>Network Allowlist Validation</strong>: Every entry in <code>whitelisted_networks</code> must conform to CAIP-2 format (e.g., <code>eip155:42161</code>).</li><li><strong>Circuit Breaker Threshold Sanity</strong>: <code>circuit_breaker_max_rpm &gt;= 1</code>, preventing invalid zero thresholds from tripping the circuit breaker immediately.</li></ol><hr><h2 id="_4-immutable-snapshot-generation-hash-fingerprint-algorithm" tabindex="-1">4. Immutable Snapshot Generation &amp; Hash Fingerprint Algorithm <a class="header-anchor" href="#_4-immutable-snapshot-generation-hash-fingerprint-algorithm" aria-label="Permalink to &quot;4. Immutable Snapshot Generation &amp; Hash Fingerprint Algorithm&quot;">​</a></h2><p>Once static validation passes and publication is confirmed, the control plane executes the following atomic steps:</p><ol><li><strong>Version Number Allocation</strong>: Queries <code>MAX(version_number) + 1</code> and allocates a new <code>version_id</code> (e.g., <code>ver_...</code>).</li><li><strong>Canonical JSON Serialization</strong>: <ul><li>Extracts all routes and policies with <code>status=&#39;active&#39;</code> under the tenant.</li><li>Sorts entries lexicographically in ascending order by <code>route_id</code> and <code>policy_id</code>.</li><li>Strips insignificant whitespace and serializes into a canonical JSON string.</li></ul></li><li><strong>Deterministic Fingerprint Calculation</strong>: $$\\text{snapshotHash} = \\text{&quot;sha256:&quot;} + \\text{SHA256}(\\text{Canonical_JSON})$$</li><li><strong>Atomic Persistence</strong>: <ul><li>Inserts the new record into <code>ap_config_version</code>.</li><li>Marks the previously <code>is_active=true</code> record as <code>false</code>.</li><li>Emits a version change notification (<code>LISTEN/NOTIFY</code>).</li></ul></li></ol><hr><h2 id="_5-gateway-runtime-cache-refresh-protocol" tabindex="-1">5. Gateway Runtime Cache &amp; Refresh Protocol <a class="header-anchor" href="#_5-gateway-runtime-cache-refresh-protocol" aria-label="Permalink to &quot;5. Gateway Runtime Cache &amp; Refresh Protocol&quot;">​</a></h2><p>The Go Gateway data plane uses a hybrid <strong>Push (event-driven) + Pull (periodic polling)</strong> architecture to guarantee real-time, loss-free configuration updates:</p>',15)),(a(),n(l,null,{default:t(()=>[s(o,{id:"mermaid-302",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20Admin%20as%20Administrator%20(Web%20Console)%0A%20%20%20%20participant%20CP%20as%20Control%20Plane%0A%20%20%20%20participant%20PG%20as%20PostgreSQL%20(ap_config_version)%0A%20%20%20%20participant%20GW%20as%20Go%20Gateway%20(Data%20Plane)%0A%0A%20%20%20%20Admin-%3E%3ECP%3A%20Click%20%22Confirm%20Publish%22%0A%20%20%20%20CP-%3E%3ECP%3A%20Pass%20static%20validation%20%26%20compute%20SHA-256%20snapshot%20fingerprint%0A%20%20%20%20CP-%3E%3EPG%3A%20INSERT%20ap_config_version%20(active%3Dtrue)%0A%20%20%20%20CP-%3E%3EPG%3A%20NOTIFY%20config_update%2C%20'%7B%22tenant_id%22%3A%20%22ten_xxx%22%2C%20%22version%22%3A%203%7D'%0A%20%20%20%20%0A%20%20%20%20par%20Real-Time%20Push%20Path%0A%20%20%20%20%20%20%20%20PG--%3E%3EGW%3A%20Receive%20LISTEN%20change%20notification%0A%20%20%20%20%20%20%20%20GW-%3E%3EPG%3A%20Fetch%20new%20snapshot%20JSON%0A%20%20%20%20%20%20%20%20GW-%3E%3EGW%3A%20Verify%20SHA-256%20fingerprint%20integrity%0A%20%20%20%20%20%20%20%20GW-%3E%3EGW%3A%20RCU%20atomic%20swap%20of%20in-memory%20routing%20table%20pointer%0A%20%20%20%20and%20Periodic%20Pull%20Fallback%20Path%20(Every%2030s)%0A%20%20%20%20%20%20%20%20GW-%3E%3EPG%3A%20SELECT%20version_number%2C%20snapshot_hash%20WHERE%20is_active%3Dtrue%0A%20%20%20%20%20%20%20%20opt%20Local%20fingerprint%20differs%20from%20database%20fingerprint%0A%20%20%20%20%20%20%20%20%20%20%20%20GW-%3E%3EGW%3A%20Trigger%20forced%20hot-reload%20refresh%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<hr><h2 id="_6-fault-tolerance-fail-safe-degradation" tabindex="-1">6. Fault Tolerance &amp; Fail-Safe Degradation <a class="header-anchor" href="#_6-fault-tolerance-fail-safe-degradation" aria-label="Permalink to &quot;6. Fault Tolerance &amp; Fail-Safe Degradation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure Scenario</th><th>Gateway Runtime Defense Behavior</th><th>Security Guarantee</th></tr></thead><tbody><tr><td><strong>Control Plane Outage / Network Partition</strong></td><td>Gateway continues serving traffic using the <strong>current in-memory configuration snapshot and local disk backup</strong>.</td><td>Ensures continuous availability of published services; control-plane faults never disrupt data-plane forwarding or billing.</td></tr><tr><td><strong>Cold Start with Database Unreachable</strong></td><td>If the Gateway cannot fetch any snapshot on initial startup and no local disk cache exists, it enforces <strong>Fail-Closed</strong> behavior and returns <code>503 Service Unavailable</code> for all requests.</td><td>Prevents unauthenticated or unpriced external calls from bypassing risk controls and leaking financial exposure.</td></tr><tr><td><strong>Snapshot Hash Verification Failure (Tamper Alert)</strong></td><td>If the recomputed hash of a fetched snapshot does not match its declared <code>snapshotHash</code>, the Gateway rejects the update, retains the existing configuration, and logs a critical security alert.</td><td>Protects against transit hijacking or unauthorized database tampering.</td></tr></tbody></table><hr><h2 id="_7-one-click-rollback" tabindex="-1">7. One-Click Rollback <a class="header-anchor" href="#_7-one-click-rollback" aria-label="Permalink to &quot;7. One-Click Rollback&quot;">​</a></h2><p>If an issue arises after publishing new rules, an administrator can execute a sub-second one-click rollback from the console:</p><ol><li>The administrator selects a historical target version (e.g., rolling back from <code>v3</code> to <code>v1</code>).</li><li>The system reads <code>snapshot_json</code> from <code>v1</code> and creates a new auto-incremented version record <code>v4</code> (<code>change_summary: &quot;Rollback to version v1&quot;</code>) whose payload and hash are identical to <code>v1</code>.</li><li><code>v4</code> is marked <code>active</code>.</li><li>The Gateway completes an atomic pointer swap within milliseconds, restoring service behavior to the known-good historical state.</li></ol>',7))])}const y=c(u,[["render",g]]);export{A as __pageData,y as default};
